/**
 * useReferenceSearch — one cross-type search seam that returns `LobuRef[]` for
 * the reference picker (and, via the picker, the chat @-mention composer).
 *
 * It composes the per-type hooks the app already ships (useEntities,
 * useConnections, useConnectorDefinitions, useBehaviorsList, useAllFeeds,
 * useEntityTypes), normalizes each row to a `LobuRef` with the object's real
 * frontend route, and filters by `kinds` + a fuzzy `query`. This is the
 * command palette's fan-out generalized — the palette, the chat @-mention, and
 * the behavior prompt editor all consume it.
 *
 * `metric` is synthetic: it's an `<entity_type>.<measure>` pair from an entity
 * type's metrics_config, not a stored object (id/label = the value). `event` is
 * still not wired (needs the content-search endpoint).
 */

import { useMemo } from "react";
import { useBehaviorsList } from "@/hooks/use-behaviors";
import {
	type EntityWithChildren,
	useEntities,
	useEntityTypes,
} from "@/lib/api";
import {
	useAllFeeds,
	useConnections,
	useConnectorDefinitions,
} from "@/lib/api/connections";
import { buildMemoryEntityScopePath } from "@/lib/memory-browse";
import {
	type BehaviorSkillOption,
	selectableSkills,
} from "@/lib/behavior-skills";
import type { LobuRef, LobuRefKind } from "@/lib/references";
import { buildEntityUrl } from "@/lib/url";

export interface ReferenceSearchOptions {
	/** Owner slug for building object routes (from useOrgContext().currentOwner). */
	owner: string | null | undefined;
	/** Org id for the underlying list hooks. */
	organizationId: string | null | undefined;
	/** Which object families to include. */
	kinds: LobuRefKind[];
	/** Fuzzy filter over label; empty string returns all (capped by `limit`). */
	query: string;
	/** Max results per kind after filtering. Defaults to 8. */
	limitPerKind?: number;
	/** Gate the network fan-out (e.g. only when the picker/popover is open). */
	enabled?: boolean;
	/**
	 * Skill library for the `skill` kind, supplied by the caller.
	 *
	 * Every other kind here is org-scoped and fetched by this hook. Skills are
	 * AGENT-scoped (`agents.skills_config`), so there is no org-wide list to
	 * fetch and no agent id in these options. The only surface that offers skill
	 * chips is the Behavior composer, which already has the owning agent's
	 * library loaded — it passes it in rather than making this seam
	 * agent-aware.
	 */
	skills?: BehaviorSkillOption[];
	/** Agent whose skills page the chips link to. Required with `skills`. */
	skillAgentId?: string | null;
}

export interface ReferenceSearchResult {
	refs: LobuRef[];
	isLoading: boolean;
}

const DEFAULT_LIMIT = 8;
const MEMBER_ENTITY_TYPE = "$member";

/** Recursively flatten the entity tree, keeping each node's addressing path. */
function flattenEntities(nodes: EntityWithChildren[]): EntityWithChildren[] {
	const out: EntityWithChildren[] = [];
	for (const node of nodes) {
		out.push(node);
		if (node.children?.length) out.push(...flattenEntities(node.children));
	}
	return out;
}

function matches(label: string, q: string): boolean {
	return q === "" || label.toLowerCase().includes(q);
}

export function useReferenceSearch(
	options: ReferenceSearchOptions,
): ReferenceSearchResult {
	const {
		owner,
		organizationId,
		kinds,
		query,
		enabled = true,
		skills,
		skillAgentId,
	} = options;
	const limit = options.limitPerKind ?? DEFAULT_LIMIT;
	const q = query.trim().toLowerCase();

	// Per-kind enable flags as plain booleans, so the memo below has honest
	// primitive dependencies (no closure over `kinds`/`enabled`).
	const wantEntity = enabled && kinds.includes("entity");
	const wantConnection = enabled && kinds.includes("connection");
	const wantConnector = enabled && kinds.includes("connector");
	const wantBehavior = enabled && kinds.includes("behavior");
	const wantMember = enabled && kinds.includes("member");
	const wantFeed = enabled && kinds.includes("feed");
	// `metric` reuses the entity-types list (its declared measures), so it shares
