// Local sink for browser-captured screenshots.
//
// The screenshot bytes must never pass through the agent's context (~500KB of
// base64 per shot). The Lobu sandbox cannot reach this host, but the paired
// Chrome extension runs here — so the data URL is handed to `evaluate` and the
// page POSTs it to this receiver. Body is text/plain so the request stays a
// CORS "simple request" and skips preflight.
import { createServer } from "node:http";
import { writeFileSync } from "node:fs";
import path from "node:path";

const OUT_DIR = "/private/tmp/claude-501/-Users-burakemre-Code-lobu/3d24866b-b631-44fd-a5da-05ad63d65961/scratchpad/shots";

createServer((req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "*");
  if (req.method === "OPTIONS") return res.writeHead(204).end();

  const name = new URL(req.url, "http://x").searchParams.get("name") || "shot";
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    const b64 = body.includes(",") ? body.slice(body.indexOf(",") + 1) : body;
    const buf = Buffer.from(b64, "base64");
    const file = path.join(OUT_DIR, `${name}.png`);
    writeFileSync(file, buf);
    console.log(`saved ${file} ${buf.length} bytes`);
    res.writeHead(200).end("ok");
  });
}).listen(5200, "127.0.0.1", () => console.log("receiver on 5200"));

